def rettangolo(b, h):
    """Rettangolo b × h: area, baricentro dal bordo inferiore, inerzia baricentrica."""
    return {"A": b * h, "yG": h / 2, "Ix": b * h**3 / 12}

import math


def cerchio(d):
    return {"A": math.pi * d**2 / 4, "yG": d / 2, "Ix": math.pi * d**4 / 64}


def tubo(D, t):
    d = D - 2 * t
    return {"A": math.pi * (D**2 - d**2) / 4, "yG": D / 2, "Ix": math.pi * (D**4 - d**4) / 64}

def componi(parti):
    """Somma più sezioni: parti = [(sezione, quota del bordo inferiore), ...]."""
    A = sum(s["A"] for s, _ in parti)
    yG = sum(s["A"] * (y0 + s["yG"]) for s, y0 in parti) / A
    Ix = sum(s["Ix"] + s["A"] * (y0 + s["yG"] - yG) ** 2 for s, y0 in parti)
    return {"A": A, "yG": yG, "Ix": Ix}

def sezione_T(b, tf, h, tw):
    anima = rettangolo(tw, h - tf)
    ala = rettangolo(b, tf)
    return componi([(anima, 0), (ala, h - tf)])

def sigma_max(M, sez, h):
    ymax = max(sez["yG"], h - sez["yG"])
    return M * ymax / sez["Ix"]


def verifica(M, sez, h, fyd):
    s = sigma_max(M, sez, h)
    return s, s <= fyd

def tabella(catalogo):
    ordinate = sorted(catalogo.items(), key=lambda kv: kv[1]["Ix"], reverse=True)
    return [f"{nome:<10}{s['A']:>10.0f}{s['Ix']:>14.0f}" for nome, s in ordinate]


if __name__ == "__main__":
    cat = {
        "R100x200": rettangolo(100, 200),
        "T120": sezione_T(120, 10, 150, 8),
        "tubo60x5": tubo(60, 5),
    }
    print(f"{'sezione':<10}{'A [mm²]':>10}{'Ix [mm⁴]':>14}")
    print("\n".join(tabella(cat)))
